CREATE OR REPLACE FUNCTION public.app_student_add_community_post(p_community_id uuid, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_member BOOLEAN;
    v_post_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    IF p_content IS NULL OR LENGTH(TRIM(p_content)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'empty_content');
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app.community_memberships m
        WHERE m.community_id = p_community_id
          AND m.user_id = v_user_id
          AND m.is_active = TRUE
    ) INTO v_is_member;

    IF NOT v_is_member THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_member');
    END IF;

    INSERT INTO app.community_posts (community_id, author_id, content)
    VALUES (p_community_id, v_user_id, TRIM(p_content))
    RETURNING id INTO v_post_id;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'post_id', v_post_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_add_community_post(p_community_id uuid, p_content text, p_type text DEFAULT 'text'::text, p_media_url text DEFAULT NULL::text, p_reply_to_post_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_member BOOLEAN;
    v_post_id UUID;
    v_type TEXT := NULLIF(TRIM(COALESCE(p_type, '')), '');
    v_media_url TEXT := NULLIF(TRIM(COALESCE(p_media_url, '')), '');
    v_reply_to_post_id UUID := p_reply_to_post_id;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    IF (p_content IS NULL OR LENGTH(TRIM(p_content)) = 0)
       AND (v_media_url IS NULL OR v_media_url = '') THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'empty_content');
    END IF;

    IF v_type IS NULL THEN
        v_type := 'text';
    ELSE
        v_type := LOWER(v_type);
        IF v_type NOT IN ('text', 'image', 'file', 'audio') THEN
            v_type := 'text';
        END IF;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app.community_memberships m
        WHERE m.community_id = p_community_id
          AND m.user_id = v_user_id
          AND m.is_active = TRUE
    ) INTO v_is_member;

    IF NOT v_is_member THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_member');
    END IF;

    INSERT INTO app.community_posts (
        community_id,
        author_id,
        content,
        type,
        media_url,
        reply_to_post_id
    )
    VALUES (
        p_community_id,
        v_user_id,
        TRIM(p_content),
        v_type,
        v_media_url,
        v_reply_to_post_id
    )
    RETURNING id INTO v_post_id;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'post_id', v_post_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_send_direct_message(p_conversation_id uuid, p_content text, p_type text DEFAULT 'text'::text, p_media_url text DEFAULT NULL::text, p_reply_to_message_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_conv RECORD;
  v_msg_id UUID;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  SELECT id, user_a, user_b INTO v_conv
    FROM app.direct_conversations
   WHERE id = p_conversation_id;

  IF v_conv IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'conversation_not_found');
  END IF;

  IF v_uid != v_conv.user_a AND v_uid != v_conv.user_b THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_participant');
  END IF;

  IF TRIM(COALESCE(p_content, '')) = '' AND TRIM(COALESCE(p_media_url, '')) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'empty_message');
  END IF;

  INSERT INTO app.direct_messages (conversation_id, sender_id, content, type, media_url, reply_to_message_id)
  VALUES (p_conversation_id, v_uid, TRIM(p_content), COALESCE(p_type, 'text'), p_media_url, p_reply_to_message_id)
  RETURNING id INTO v_msg_id;

  UPDATE app.direct_conversations
     SET last_message_at = NOW()
   WHERE id = p_conversation_id;

  RETURN jsonb_build_object('success', true, 'message_id', v_msg_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_list_direct_messages(p_conversation_id uuid, p_limit integer DEFAULT 50, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_conv RECORD;
  v_result JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  SELECT id, user_a, user_b INTO v_conv
    FROM app.direct_conversations
   WHERE id = p_conversation_id;

  IF v_conv IS NULL OR (v_uid != v_conv.user_a AND v_uid != v_conv.user_b) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_participant');
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.created_at ASC), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT dm.id, dm.sender_id, dm.content, dm.type, dm.media_url,
           dm.reply_to_message_id, dm.is_deleted, dm.edited_at, dm.created_at,
           COALESCE(s.full_name, u.email) AS sender_display_name
      FROM app.direct_messages dm
      LEFT JOIN auth.users u ON u.id = dm.sender_id
      LEFT JOIN app.students s ON s.id = dm.sender_id
     WHERE dm.conversation_id = p_conversation_id
       AND dm.is_deleted = false
       AND (p_before IS NULL OR dm.created_at < p_before)
     ORDER BY dm.created_at DESC
     LIMIT LEAST(p_limit, 100)
  ) t;

  RETURN jsonb_build_object('success', true, 'messages', v_result);
END;
$function$
